  @Test(timeout = 4000)
  public void test2()  throws Throwable  {
    // Given: a graph and an inserted self-loop to exercise adjacency iteration
    Grafo grafo0 = new Grafo(1165);
    grafo0.insereAresta(0, 0, (-435));

    // When: request the next adjacency for vertex 0
    Grafo.Aresta grafo_Aresta0 = grafo0.proxAdj(0);

    // Then: adjacency must reflect the recently inserted edge and the graph size must be intact
    assertNotNull("proxAdj should return a non-null adjacency for vertex 0 after insertion", grafo_Aresta0);
    assertEquals("Adjacency edge weight should be -435", (-435), grafo_Aresta0.peso());
    assertEquals("Adjacency edge v1 should be 0", 0, grafo_Aresta0.v1());
    assertEquals("Adjacency edge v2 should be 0", 0, grafo_Aresta0.v2());
    assertEquals("Number of vertices should remain 1165", 1165, grafo0.numVertices());
  }

